<?php use App\Support\App;$u=App::requireAuth();$db=App::db();$q=$db->prepare('SELECT COUNT(*) total,SUM(status="processing") processing,SUM(status="success") success FROM orders WHERE user_id=?');$q->execute([$u['id']]);$s=$q->fetch();$r=$db->prepare('SELECT o.order_number,o.imei,o.status,p.name product_name FROM orders o JOIN products p ON p.id=o.product_id WHERE o.user_id=? ORDER BY o.id DESC LIMIT 6');$r->execute([$u['id']]);$recent=$r->fetchAll();$title='Dashboard';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row sm:items-end justify-between gap-4"><div><h1 class="page-title">Good to see you.</h1><p class="page-sub">Overview akun dan aktivitas IMEI terbaru.</p></div><a href="/order" class="btn btn-dark"><i data-lucide="plus"></i>New order</a></div><section class="grid grid-cols-2 lg:grid-cols-4 gap-3 mt-6"><div class="saas-card metric col-span-2 sm:col-span-1"><div class="metric-label">Available balance</div><div class="metric-value">Rp<?=number_format($u['balance'],0,',','.')?></div><a href="/deposit" class="text-xs font-semibold mt-3 inline-block">+ Add balance</a></div><?php foreach([['Total orders',$s['total']??0,'shopping-bag'],['Processing',$s['processing']??0,'loader-circle'],['Success',$s['success']??0,'circle-check']] as $x):?><div class="saas-card metric"><div class="flex justify-between"><span class="metric-label"><?=$x[0]?></span><i class="w-4 h-4 text-zinc-400" data-lucide="<?=$x[2]?>"></i></div><div class="metric-value"><?=$x[1]?></div></div><?php endforeach?></section><section class="grid lg:grid-cols-[1.4fr_.6fr] gap-4 mt-5"><div class="saas-card overflow-hidden"><div class="p-5 border-b flex justify-between" style="border-color:var(--line)"><div><b>Recent orders</b><p class="text-xs text-zinc-500 mt-1">Aktivitas terbaru akun Anda</p></div><a class="text-xs font-semibold" href="/order">Create order →</a></div><div class="overflow-auto"><?php if(!$recent):?><div class="p-10 text-center text-sm text-zinc-500"><i data-lucide="inbox" class="mx-auto mb-3"></i>Belum ada order.</div><?php else:?><table class="w-full text-sm"><thead><tr><th>Order</th><th>Service</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $o):?><tr class="border-t" style="border-color:var(--line)"><td><b><?=htmlspecialchars($o['order_number'])?></b><div class="text-xs text-zinc-500 font-mono"><?=htmlspecialchars($o['imei'])?></div></td><td><?=htmlspecialchars($o['product_name'])?></td><td><span class="badge"><?=htmlspecialchars($o['status'])?></span></td></tr><?php endforeach?></tbody></table><?php endif?></div></div><div class="saas-card p-5"><div class="w-10 h-10 rounded-xl bg-zinc-100 dark:bg-zinc-800 grid place-items-center"><i data-lucide="zap"></i></div><h2 class="font-semibold mt-4">Quick actions</h2><p class="text-sm text-zinc-500 mt-1">Akses fitur utama lebih cepat.</p><div class="grid gap-2 mt-5"><a class="btn justify-start" href="/order"><i data-lucide="smartphone"></i>Order IMEI</a><a class="btn justify-start" href="/deposit"><i data-lucide="wallet-cards"></i>Deposit balance</a><a class="btn justify-start" href="/docs"><i data-lucide="code-2"></i>API documentation</a></div></div></section><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>